SELECT r.id, r.role_code, r.role_name, r.status, r.role_type, r.order_num, r.create_time, r.update_time, r.create_user, r.update_user, IF(cu.id IS NULL OR cu.is_deleted = 1, NULL, cu.username) create_username, IF(uu.id IS NULL OR uu.is_deleted = 1, NULL, uu.username) update_username FROM sys_role r LEFT JOIN sys_user cu ON r.create_user = cu.id LEFT JOIN sys_user uu ON r.update_user = uu.id
r.is_deleted = 0
AND r.role_code LIKE CONCAT('%', #{query.roleCode}, '%')
AND r.role_name LIKE CONCAT('%', #{query.roleName}, '%')
AND r.status = #{query.status}
AND r.role_type = #{query.roleType}
ORDER BY ${orderBySql}

